import pytest

from minimum_spanning_tree import minimum_spanning_tree


def _total_weight(edges, weight_by_edge):
    """Helper: sum weights of edges, tolerant to edge orientation."""
    total = 0
    for edge in edges:
        if edge in weight_by_edge:
            total += weight_by_edge[edge]
        else:
            u, v = edge
            total += weight_by_edge[(v, u)]
    return total


def _vertices(weight_by_edge):
    """Helper: collect all vertices from edge dict."""
    verts = set()
    for (u, v) in weight_by_edge:
        verts.add(u)
        verts.add(v)
    return verts


def _connected(edges, vertices):
    """Helper: check that edges connect all vertices (undirected)."""
    if not vertices:
        return True
    adj = {v: set() for v in vertices}
    for edge in edges:
        u, v = edge
        adj[u].add(v)
        adj[v].add(u)
    start = next(iter(vertices))
    seen = {start}
    stack = [start]
    while stack:
        node = stack.pop()
        for nb in adj[node]:
            if nb not in seen:
                seen.add(nb)
                stack.append(nb)
    return seen == vertices


def test_minimum_spanning_tree_docstring_example():
    """Docstring example: expected result is {(1,2),(3,4),(1,4)}."""
    weight_by_edge = {
        (1, 2): 10,
        (2, 3): 15,
        (3, 4): 10,
        (1, 4): 10,
    }
    result = minimum_spanning_tree(weight_by_edge)
    assert set(result) == {(1, 2), (3, 4), (1, 4)}


